import { formatFrequency, formatLevel } from "@audio-ui/engine/format";
import { type ReactNode, useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  Plot,
  PlotArea,
  PlotCursor,
  PlotCurve,
  PlotGraph,
  PlotGrid,
  PlotTraceArea,
} from "@/components/audio-ui/plot";
import {
  DeviceFrame,
  DeviceHeader,
  DevicePanel,
} from "@/components/audio-ui/device-panel";
import {
  type RotaryState,
  rotaryBands,
  rotaryDevice,
} from "@/components/audio-ui/devices/rotary/device";
import type { DeviceSignal } from "@/lib/device-signal";

const MIN_HZ = 20;
const MAX_HZ = 20_000;
/** The scale a spectrum is drawn on, in dB of level: its own, behind the plot's. */
const SPECTRUM_MIN_DB = -100;
const SPECTRUM_MAX_DB = -10;
const MIN_DB = -36;
const MAX_DB = 6;
const DB_TICKS = [-24, -12, 0];
const SWITCHES = ["enabled"] as const;
const OFF = rotaryDevice.parameters
  .map((parameter) => parameter.id)
  .filter((id) => id !== "enabled");

const describePointer = (point: { x: number; y: number }) =>
  `${formatFrequency(point.x)} · ${formatLevel(point.y)}`;

interface RotaryPanelProps {
  /** Whatever the host puts at the end of the title bar: a play button, a reading. */
  children?: ReactNode;
  className?: string;
  onValueChange: (state: RotaryState) => void;
  /** Its live sound: the spectrum of what comes out, behind the drum's band and the horn's. */
  signal?: DeviceSignal;
  value: RotaryState;
}

/**
 * The face of the rotary device: the band the drum turns, dashed, and the one
 * the horn turns, split at the crossover, over its speed and its knobs.
 * Controlled like `DevicePanel`, which it uses for them. Its children sit at
 * the end of the title bar.
 */
function RotaryPanel({
  children,
  className,
  onValueChange,
  signal,
  value,
}: RotaryPanelProps) {
  const spectrum = useMemo(
    () => signal?.output.spectrum({ maxHz: MAX_HZ, minHz: MIN_HZ }),
    [signal]
  );
  const bands = useMemo(() => rotaryBands(value), [value]);
  return (
    <DeviceFrame className={cn("h-full", className)} signal={signal}>
      <DeviceHeader
        activator="enabled"
        device={rotaryDevice}
        onValueChange={onValueChange}
        value={value}
      >
        {children}
      </DeviceHeader>
      <div
        className="flex min-h-0 grow flex-col gap-2 p-2"
        data-slot="rotary-panel"
      >
        <Plot
          aria-label="The drum's band and the horn's"
          className="h-24 min-h-16 grow"
          maxX={MAX_HZ}
          maxY={MAX_DB}
          minX={MIN_HZ}
          minY={MIN_DB}
          scaleX="log"
        >
          <PlotCursor format={describePointer} />
          <PlotGrid x={{ count: 6 }} y={{ ticks: DB_TICKS }} />
          <PlotGraph>
            {spectrum ? (
              // What comes out, behind what the device does to it.
              <PlotTraceArea
                fillTo={SPECTRUM_MIN_DB}
                max={SPECTRUM_MAX_DB}
                min={SPECTRUM_MIN_DB}
                source={spectrum}
              />
            ) : null}
            <PlotCurve
              className="stroke-muted-foreground [stroke-dasharray:4_4]"
              fn={bands.drum}
            />
            <PlotArea fillTo={MIN_DB} fn={bands.horn} />
            <PlotCurve fn={bands.horn} />
          </PlotGraph>
        </Plot>
        <DevicePanel
          className="grid-cols-4"
          device={rotaryDevice}
          disabled={value.enabled ? undefined : OFF}
          exclude={SWITCHES}
          onValueChange={onValueChange}
          value={value}
        />
      </div>
    </DeviceFrame>
  );
}

export { RotaryPanel };
